import request from '@/static/js/request'

export function aaaaa(param) {
	return new Promise((resolve, reject) => {
		request({
			url: "/app/GoodsCategory/list",
			method: "POST",
			data: param,
		}).then((res) => {
			resolve(res);
		}).catch((error) => {
			uni.showToast({
				title: '服务异常.',
				icon: 'none',
				duration: 3000
			});
		})
	})
}